const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".scene{background:#a9dcef}\n.art{position:absolute;inset:0;width:100%;height:100%;display:block}\n.s0{stop-color:#7fc4e6}.s1{stop-color:#a9dcef}.s2{stop-color:#d7efe9}.s3{stop-color:#fff1cf}\n.halo{fill:#fff6d6;opacity:.35}.sun{fill:#fffbe8}\n.cw{fill:#ffffff}.cs{fill:#dcecf3}.cf{fill:#f4fbff;opacity:.9}\n.drift{animation:drift 60s ease-in-out infinite}\n.hillA{fill:#a7d1b0}.hillB{fill:#86bb92}\n.w1{fill:#7cc6cf}.w2{fill:#58aab9}.w3{fill:#3f8da3}\n.rip{fill:none;stroke:#d9f3f2;stroke-width:1.6;stroke-linecap:round;animation:shimmer 4.4s ease-in-out infinite}\n.shade{fill:#2f7487;opacity:.26}\n.amb1,.amb2{animation:swim 16s ease-in-out infinite}\n.pad{fill:#5fa66a}.padF{fill:#f6b6c8}\n.reeds{transform-box:view-box;transform-origin:376px 214px;animation:sway 6s ease-in-out infinite}\n.reed{fill:none;stroke:#4f8f5f;stroke-width:3;stroke-linecap:round}\n.bank{fill:#8fc27a}.bankD{fill:#6a9e58}\n.trunk{fill:#8a6a4a}.leafD{fill:#4f9a68}.leafL{fill:#7dc487}\n.dsh{fill:#2f7487;opacity:.24}\n.post{fill:#8a6340}.plank{fill:#c79b68}.plankLine{fill:none;stroke:#a97b4c;stroke-width:1.2}\n.bucket{fill:#7b9fb5}.bucketIn{fill:#5f8196}\n.pants{fill:#4f6d8f}.shoe{fill:#6b4a38}.shirt{fill:#e9805b}.hair{fill:#5b3b2a}.skin{fill:#f6d3b3}.eye{fill:#3a2a22}\n.hat{fill:#f1d58a}.ribbon{fill:#d9654a}\n.arm{fill:none;stroke:#e9805b;stroke-width:7;stroke-linecap:round}\n.rod{transform-box:view-box;transform-origin:182px 127px}\n.rodline{stroke:#6b4a2f;stroke-width:2.6;stroke-linecap:round}\n.fline{fill:none;stroke:#4c6672;stroke-width:1;opacity:.8}\n.bobber{transform-box:view-box;transform-origin:0 0}\n.bobStick{fill:#e14b3b}.bobR{fill:#e14b3b}.bobW{fill:#fdf6ee}\n.art[data-phase=\"idle\"] .bobber,.art[data-phase=\"result\"] .bobber{transform:translate(247px,100px)}\n.art[data-phase=\"idle\"] .bobber{animation:sway3 3.2s ease-in-out infinite}\n.art[data-phase=\"wait\"] .bobber{animation:plop .5s ease-in forwards,bob 2.6s ease-in-out infinite;animation-fill-mode:forwards,none}\n.art[data-phase=\"bite\"] .bobber{animation:dip .45s ease-in-out infinite}\n.art[data-phase=\"result\"] .rod{animation:flick .5s ease-out}\n.ring{fill:none;stroke:#e9fbff;stroke-width:1.4;opacity:0;transform-box:fill-box;transform-origin:center;animation:ringx 2.6s ease-out infinite}\n.art[data-phase=\"bite\"] .ring{animation-duration:.9s}\n.splash{fill:none;stroke:#f2fdff;stroke-width:1.8;opacity:0;transform-box:fill-box;transform-origin:center;animation:splashx .7s ease-out forwards}\n.shade.bite{opacity:0;animation:shin .4s ease-out forwards}\n.bang{transform-box:fill-box;transform-origin:50% 100%;animation:pop .25s ease-out both}\n.bangBg{fill:#fff7e0}.bangTail{fill:#fff7e0}.bangFg{fill:#e0543c}\n.jump{transform-box:view-box;transform-origin:0 0;opacity:0;animation:leap .95s cubic-bezier(.3,.6,.4,1) forwards}\n.fe{fill:#2c3a40}.fp{display:none}\n.f1 .fb{fill:#c9b27a}.f1 .ft{fill:#b59a5e}.f1 .fv{fill:#efe3bd}\n.f2 .fb{fill:#7aa7a0}.f2 .ft{fill:#5f8f89}.f2 .fv{fill:#d3e6df}\n.f3 .fb{fill:#e8683f}.f3 .ft{fill:#d4532b}.f3 .fv{fill:#f7c9a7}.f3 .fp{display:inline;fill:#fff3e6}\n.f4 .fb{fill:#aebfcd}.f4 .ft{fill:#93a7b8}.f4 .fv{fill:#e9f0f5}\n.f5 .fb{fill:#f2c230}.f5 .ft{fill:#e0a91c}.f5 .fv{fill:#fbe58a}.f5 .fp{display:inline;fill:#fff0a8}\n@keyframes drift{0%,100%{transform:translateX(-26px)}50%{transform:translateX(26px)}}\n@keyframes swim{0%,100%{transform:translateX(-30px)}50%{transform:translateX(30px)}}\n@keyframes shimmer{0%,100%{opacity:.25}50%{opacity:.8}}\n@keyframes sway{0%,100%{transform:skewX(-3deg)}50%{transform:skewX(3deg)}}\n@keyframes sway3{0%,100%{transform:translate(246px,100px) rotate(-4deg)}50%{transform:translate(248px,100px) rotate(4deg)}}\n@keyframes plop{0%{transform:translate(247px,100px)}55%{transform:translate(270px,176px)}75%{transform:translate(270px,196px)}100%{transform:translate(270px,190px)}}\n@keyframes bob{0%,100%{transform:translate(270px,190px)}50%{transform:translate(270px,192.5px)}}\n@keyframes dip{0%,100%{transform:translate(270px,190px)}30%{transform:translate(270px,199px)}60%{transform:translate(270px,192px)}}\n@keyframes flick{0%{transform:rotate(0)}30%{transform:rotate(-12deg)}100%{transform:rotate(0)}}\n@keyframes ringx{0%{transform:scale(.4);opacity:.85}100%{transform:scale(2.6);opacity:0}}\n@keyframes splashx{0%{transform:scale(.3);opacity:.9}100%{transform:scale(3.2);opacity:0}}\n@keyframes shin{to{opacity:.4}}\n@keyframes pop{0%{transform:scale(0)}70%{transform:scale(1.2)}100%{transform:scale(1)}}\n@keyframes leap{0%{transform:translate(270px,190px) rotate(0) scale(.5);opacity:0}8%{opacity:1}45%{transform:translate(212px,88px) rotate(-38deg) scale(1.2)}100%{transform:translate(122px,132px) rotate(-75deg) scale(.7);opacity:0}}\n@media (prefers-reduced-motion:reduce){.drift,.amb1,.amb2,.rip,.reeds,.ring{animation:none}.ring{opacity:0}}\n\n.game{position:relative;width:100%;height:100%;min-width:0;min-height:0;display:grid;gap:8px;padding:8px;color:var(--ink);\n  grid-template-columns:minmax(0,1fr);grid-template-rows:auto minmax(0,1fr)}\n.scene{position:relative;display:block;width:100%;min-width:0;min-height:0;aspect-ratio:4/3;padding:0;border:0;border-radius:14px;overflow:hidden;\n  cursor:pointer;touch-action:manipulation;user-select:none;-webkit-user-select:none;-webkit-tap-highlight-color:transparent;color:inherit}\n.scene:focus-visible{outline:2px solid var(--accent);outline-offset:2px}\n.hint,.toast{position:absolute;left:50%;transform:translateX(-50%);max-width:calc(100% - 16px);padding:4px 12px;border-radius:999px;\n  background:color-mix(in srgb,var(--panel-paper) 92%,transparent);color:var(--ink);border:1px solid var(--line);\n  font-size:12px;line-height:1.35;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;pointer-events:none}\n.hint{bottom:8px}\n.hint.now{background:var(--accent);color:var(--on-accent);border-color:transparent;font-weight:700;animation:hurry .45s ease-in-out infinite alternate}\n.toast{top:8px;font-weight:700}\n.toast.good{background:var(--accent);color:var(--on-accent);border-color:transparent}\n.hint .short{display:none}\n@keyframes hurry{from{transform:translateX(-50%) scale(1)}to{transform:translateX(-50%) scale(1.07)}}\n\n.hud{min-width:0;min-height:0;display:grid;gap:6px;align-content:start;padding:8px 10px;border:1px solid var(--line);border-radius:12px;\n  background:var(--panel-paper);overflow:hidden}\n.cnt{display:flex;align-items:center;gap:6px;min-width:0}\n.cnt .ico{width:30px;height:15px;flex:none}\n.lbl{font-size:12px;color:var(--muted)}\n.num{font-size:26px;font-weight:800;line-height:1;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}\n.unit{font-size:12px;color:var(--muted)}\n.dex{list-style:none;margin:0;padding:0;display:grid;gap:3px;min-height:0;overflow:auto}\n.dex li{display:grid;grid-template-columns:34px minmax(0,1fr) auto;align-items:center;gap:6px;font-size:12px;min-width:0}\n.dex .ico{width:34px;height:16px}\n.dex .ico.unk{opacity:.22;filter:grayscale(1)}\n.dex .nm{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.dex .none .nm,.dex .none .ct{color:var(--muted)}\n.dex .ct{font-variant-numeric:tabular-nums;font-weight:700}\n\n.card[data-size=\"3x3\"] .game{padding:0;gap:0;grid-template-rows:minmax(0,1fr)}\n.card[data-size=\"3x3\"] .scene{aspect-ratio:auto;height:100%;border-radius:0}\n.card[data-size=\"3x3\"] .hud{position:absolute;top:8px;left:8px;z-index:2;display:block;padding:3px 10px 3px 6px;border-radius:999px;\n  background:color-mix(in srgb,var(--panel-paper) 92%,transparent);pointer-events:none}\n.card[data-size=\"3x3\"] .num{font-size:18px}\n.card[data-size=\"3x3\"] .dex{display:none}\n.card[data-size=\"3x3\"] .toast{top:38px}\n.card[data-size=\"3x3\"] .hint .long{display:none}\n.card[data-size=\"3x3\"] .hint .short{display:inline}\n\n.card[data-size=\"6x3\"] .game{grid-template-columns:minmax(0,1.3fr) minmax(0,1fr);grid-template-rows:minmax(0,1fr)}\n.card[data-size=\"6x3\"] .scene{aspect-ratio:auto;height:100%}\n.card[data-size=\"6x3\"] .hud{padding:6px 8px;gap:4px}\n.card[data-size=\"6x3\"] .num{font-size:22px}\n.card[data-size=\"6x3\"] .dex li{font-size:11px;grid-template-columns:30px minmax(0,1fr) auto}\n.card[data-size=\"6x3\"] .dex .ico{width:30px;height:14px}\n.card[data-size=\"6x3\"] .hint .long{display:none}\n.card[data-size=\"6x3\"] .hint .short{display:inline}\n\n.card[data-size=\"3x6\"] .game{padding:8px}\n.card[data-size=\"3x6\"] .num{font-size:28px}\n\n.card[data-size=\"6x6\"] .game{padding:10px;gap:10px}\n.card[data-size=\"6x6\"] .scene{aspect-ratio:16/10}\n.card[data-size=\"6x6\"] .hud{padding:8px 12px}\n.card[data-size=\"6x6\"] .num{font-size:30px}\n.card[data-size=\"6x6\"] .dex{grid-template-columns:repeat(5,minmax(0,1fr));gap:6px}\n.card[data-size=\"6x6\"] .dex li{grid-template-columns:minmax(0,1fr);justify-items:center;text-align:center;gap:2px;font-size:12px}\n.card[data-size=\"6x6\"] .dex .ico{width:44px;height:20px}\n.card[data-size=\"6x6\"] .hint{font-size:13px}\n@media (prefers-reduced-motion:reduce){.hint.now{animation:none}}\n";
const BITE_MS=1600,RESULT_MS=2600,GUARD_MS=380;
const FISH=[
  {id:'crucian',name:'小鲫鱼',w:40,cls:'f1'},
  {id:'trout',name:'青鳟鱼',w:25,cls:'f2'},
  {id:'koi',name:'红锦鲤',w:20,cls:'f3'},
  {id:'perch',name:'银鲈鱼',w:10,cls:'f4'},
  {id:'golden',name:'金鲤王',w:5,cls:'f5'}
];
function pickFish(){
  let r=Math.random()*FISH.reduce((a,f)=>a+f.w,0);
  for(const f of FISH){r-=f.w;if(r<0)return f;}
  return FISH[0];
}
function fishById(id){return FISH.find(f=>f.id===id)||FISH[0];}
function S(el,tag,cls,attrs,...kids){return el(tag,{class:cls||null,...(attrs||{})},...kids);}
function loop(ui,sec){return {animationDuration:sec+'s',animationDelay:(-((Date.now()-ui.t0)%(sec*1000)))+'ms'};}

function fishShape(el,cls){
  return S(el,'g','fs '+cls,null,
    S(el,'path','ft',{d:'M-13 0 L-25 -8 L-22 0 L-25 8 Z'}),
    S(el,'path','fb',{d:'M-17 0 C-9 -10 9 -10 17 0 C9 10 -9 10 -17 0 Z'}),
    S(el,'ellipse','fp',{cx:-3,cy:-3,rx:6,ry:3}),
    S(el,'path','fv',{d:'M-9 3 C-3 7 6 7 12 2 C6 9 -4 9 -9 3 Z'}),
    S(el,'circle','fe',{cx:10,cy:-2,r:1.7}));
}
function fishIcon(el,cls,known){
  return S(el,'svg','ico'+(known?'':' unk'),{viewBox:'-27 -12 54 24','aria-hidden':'true'},fishShape(el,cls));
}

function cloud(el,ui,x,y,s,sec){
  return S(el,'g','drift',{style:loop(ui,sec)},
    S(el,'g',null,{transform:'translate('+x+' '+y+') scale('+s+')'},
      S(el,'ellipse','cs',{cx:0,cy:11,rx:48,ry:12}),
      S(el,'ellipse','cw',{cx:-20,cy:3,rx:22,ry:15}),
      S(el,'ellipse','cw',{cx:4,cy:-7,rx:27,ry:20}),
      S(el,'ellipse','cw',{cx:30,cy:2,rx:21,ry:14}),
      S(el,'ellipse','cw',{cx:0,cy:8,rx:46,ry:10})));
}

function ripple(el,ui,d,sec){return S(el,'path','rip',{d:d,style:loop(ui,sec)});}

function scenery(el,ui){
  return S(el,'g','scenery',null,
    S(el,'defs',null,null,S(el,'linearGradient',null,{id:'skyg',x1:0,y1:0,x2:0,y2:1},
      S(el,'stop','s0',{offset:'0'}),S(el,'stop','s1',{offset:'.45'}),S(el,'stop','s2',{offset:'.8'}),S(el,'stop','s3',{offset:'1'}))),
    S(el,'rect',null,{x:0,y:0,width:400,height:170,fill:'url(#skyg)'}),
    S(el,'circle','halo',{cx:330,cy:58,r:52}),
    S(el,'circle','sun',{cx:330,cy:58,r:27}),
    cloud(el,ui,60,52,.95,64),cloud(el,ui,214,34,.7,52),cloud(el,ui,338,98,.8,76),
    S(el,'g','far',null,
      S(el,'ellipse','cf',{cx:292,cy:124,rx:58,ry:26}),
      S(el,'ellipse','cf',{cx:326,cy:112,rx:40,ry:30}),
      S(el,'ellipse','cf',{cx:262,cy:130,rx:44,ry:18})),
    S(el,'path','hillA',{d:'M0 150 C34 112 84 126 126 134 C170 142 206 100 262 112 C312 122 350 104 400 126 L400 164 L0 164 Z'}),
    S(el,'path','hillB',{d:'M0 156 C48 134 96 146 150 150 C214 154 252 128 312 134 C352 138 382 132 400 140 L400 166 L0 166 Z'}),
    S(el,'rect','w1',{x:0,y:158,width:400,height:142}),
    S(el,'rect','w2',{x:0,y:204,width:400,height:96}),
    S(el,'rect','w3',{x:0,y:254,width:400,height:46}),
    ripple(el,ui,'M236 176 q10 -3 20 0 t20 0',4.2),
    ripple(el,ui,'M300 212 q12 -3 24 0 t24 0',5.1),
    ripple(el,ui,'M200 236 q10 -3 20 0 t20 0',3.7),
    ripple(el,ui,'M120 224 q10 -3 20 0 t20 0',4.8),
    ripple(el,ui,'M322 266 q10 -3 20 0 t20 0',5.6),
    S(el,'ellipse','shade amb1',{cx:230,cy:250,rx:16,ry:5,style:loop(ui,15)}),
    S(el,'ellipse','shade amb2',{cx:300,cy:216,rx:12,ry:4,style:loop(ui,19)}),
    S(el,'ellipse','pad',{cx:332,cy:236,rx:17,ry:6}),
    S(el,'ellipse','pad',{cx:354,cy:250,rx:12,ry:4.5}),
    S(el,'circle','padF',{cx:336,cy:232,r:3.2}),
    S(el,'g','reeds',{style:loop(ui,6)},
      S(el,'path','reed',{d:'M376 214 Q372 178 381 140'}),
      S(el,'path','reed',{d:'M386 216 Q388 182 394 150'}),
      S(el,'path','reed',{d:'M368 214 Q366 188 360 160'})),
    S(el,'path','bankD',{d:'M0 160 Q56 168 98 162 L98 170 Q56 182 0 186 Z'}),
    S(el,'path','bank',{d:'M0 148 Q44 144 98 150 L98 162 Q56 170 0 168 Z'}),
    S(el,'rect','trunk',{x:34,y:104,width:9,height:50,rx:3}),
    S(el,'circle','leafD',{cx:40,cy:92,r:24}),S(el,'circle','leafD',{cx:22,cy:102,r:17}),S(el,'circle','leafD',{cx:58,cy:100,r:19}),
    S(el,'circle','leafL',{cx:34,cy:86,r:14}),S(el,'circle','leafL',{cx:50,cy:92,r:9}),S(el,'circle','leafL',{cx:18,cy:98,r:8}),
    S(el,'rect','dsh',{x:72,y:162,width:126,height:8,rx:3}),
    S(el,'rect','post',{x:80,y:159,width:6,height:44}),S(el,'rect','post',{x:150,y:159,width:6,height:40}),S(el,'rect','post',{x:186,y:159,width:6,height:42}),
    S(el,'rect','plank',{x:70,y:150,width:126,height:9,rx:1.5}),
    S(el,'path','plankLine',{d:'M88 150V159M106 150V159M124 150V159M142 150V159M160 150V159M178 150V159'}),
    S(el,'path','bucket',{d:'M112 134 L132 134 L129 150 L115 150 Z'}),
    S(el,'ellipse','bucketIn',{cx:122,cy:134,rx:10,ry:2.6}));
}

function kid(el,rodStyle,hang){
  return S(el,'g','kid',null,
    S(el,'rect','pants',{x:168,y:138,width:34,height:11,rx:5.5}),
    S(el,'rect','pants',{x:194,y:142,width:11,height:30,rx:5.5}),
    S(el,'ellipse','shoe',{cx:202,cy:174,rx:9,ry:4.5}),
    S(el,'rect','shirt',{x:152,y:112,width:24,height:38,rx:11}),
    S(el,'ellipse','hair',{cx:161,cy:100,rx:11,ry:10}),
    S(el,'circle','skin',{cx:165,cy:100,r:11}),
    S(el,'circle','eye',{cx:170,cy:101,r:1.3}),
    S(el,'ellipse','hat',{cx:165,cy:92,rx:21,ry:5.5}),
    S(el,'path','hat',{d:'M151 92 Q165 66 179 92 Z'}),
    S(el,'rect','ribbon',{x:152,y:86,width:26,height:4,rx:1.5}),
    S(el,'path','arm',{d:'M164 120 Q176 124 183 126'}),
    S(el,'circle','skin',{cx:184,cy:126,r:3.6}),
    S(el,'g','rod',{style:rodStyle},
      S(el,'line','rodline',{x1:182,y1:127,x2:246,y2:70}),...hang));
}

function bang(el,e){
  return S(el,'g','bang',{style:{animationDelay:(-e)+'ms'}},
    S(el,'path','bangTail',{d:'M146 80 L152 90 L158 80 Z'}),
    S(el,'rect','bangBg',{x:143,y:50,width:18,height:30,rx:9}),
    S(el,'rect','bangFg',{x:150.2,y:56,width:3.6,height:11,rx:1.8}),
    S(el,'circle','bangFg',{cx:152,cy:73,r:2.3}));
}

function buildArt(el,ui,g,fishCls){
  const e=Math.max(0,Date.now()-(g.at||Date.now())),ph=g.phase;
  const wet=ph==='wait'||ph==='bite';
  const bobStyle=ph==='wait'?{animationDelay:(-e)+'ms,'+(500-e)+'ms'}:ph==='bite'?{animationDelay:(-e)+'ms'}:loop(ui,3.2);
  const rodStyle=ph==='result'?{animationDelay:(-e)+'ms'}:{};
  const line=wet?'M246 70 Q268 120 270 179':'M246 70 L247 91';
  const rings=[];
  if(wet)rings.push(S(el,'ellipse','ring r1',{cx:270,cy:193,rx:8,ry:2.5,style:{animationDelay:(ph==='bite'?-e:-(e%2600))+'ms'}}),
                    S(el,'ellipse','ring r2',{cx:270,cy:193,rx:8,ry:2.5,style:{animationDelay:(ph==='bite'?-(e+450):-((e+1300)%2600))+'ms'}}));
  const extra=[];
  if(ph==='bite')extra.push(S(el,'ellipse','shade bite',{cx:266,cy:204,rx:16,ry:5,style:{animationDelay:(-e)+'ms'}}),bang(el,e));
  if(ph==='result'&&g.kind==='catch'){
    extra.push(S(el,'ellipse','splash',{cx:270,cy:193,rx:9,ry:3,style:{animationDelay:(-e)+'ms'}}),
               S(el,'g','jump',{style:{animationDelay:(-e)+'ms'}},fishShape(el,fishCls)));
  }
  // 空中的线和浮标挂在鱼竿上跟着甩；入水后留在水面
  const lineEl=S(el,'path','fline',{d:line});
  const bobEl=S(el,'g','bobber',{style:bobStyle},
    S(el,'rect','bobStick',{x:-1,y:-11,width:2,height:7}),
    S(el,'path','bobR',{d:'M-5.5 0 A5.5 5.5 0 0 1 5.5 0 Z'}),
    S(el,'path','bobW',{d:'M-5.5 0 A5.5 5.5 0 0 0 5.5 0 Z'}));
  return S(el,'svg','art',{viewBox:'0 0 400 300',preserveAspectRatio:'xMidYMid slice','data-phase':ph,'aria-hidden':'true'},
    scenery(el,ui),
    ...rings,
    kid(el,rodStyle,wet?[]:[lineEl,bobEl]),
    ...(wet?[lineEl,bobEl]:[]),
    ...extra);
}

const HINT={idle:['点击抛竿','抛竿'],wait:['等鱼上钩…先别起钩','等待'],bite:['快！点击起钩','起钩！'],result:['再来一次：点击抛竿','再抛']};

function toastText(g){
  if(g.phase!=='result')return '';
  if(g.kind==='catch'){
    const f=fishById(g.fish);
    return g.failed?('钓到了'+f.name+'，但没能记上，再试一次'):('钓到了！'+f.name);
  }
  return g.kind==='early'?'起钩太早，鱼被吓跑了':'慢了一步，鱼溜走了';
}

function mount(ctx){
  const {root,el,state,ui,update,redraw}=ctx;
  if(!ui.t0)ui.t0=Date.now();
